const fs = require('fs');

const line1 = "조나단/이은석\t\t\t\t\t\t\t\t\t애니메이션\t\t\t\t\t\t";
const line2 = "족보만드는곳족보관\t\t\t\t\t051-248-9529\t\t중구\t부산 중구 구덕로 19\t출판\t\t\t\t\t\t";

[line1, line2].forEach((l, i) => {
  const parts = l.split('\t');
  console.log('Line', i, 'parts length:', parts.length);
  parts.forEach((p, idx) => {
    if (p.trim()) console.log('  idx', idx, ':', JSON.stringify(p));
  });
});

